mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g5-1/bot.mjs';

const H = 3600_000;
const t0 = new Date('2026-10-23T10:00:00Z');
const at = (ms) => new Date(t0.getTime() + ms);
let n = 0;
const ok = (msg, fn) => { fn(); n++; console.log('ok', msg); };

ok('never-contacted user blocked for freeform and template', () => {
  assert.deepEqual(check('new1', 'freeform', at(0)), { allowed: false, rule: 'no_prior_inbound' });
  assert.deepEqual(check('new1', 'template', at(0)), { allowed: false, rule: 'no_prior_inbound' });
});

ok('freeform allowed inside 24h, template allowed', () => {
  onInbound('u1', 'my line is down', at(0));
  assert.deepEqual(check('u1', 'freeform', at(23 * H)), { allowed: true, rule: null });
  assert.deepEqual(check('u1', 'template', at(23 * H)), { allowed: true, rule: null });
});

ok('freeform blocked at/after 24h, template still allowed', () => {
  assert.deepEqual(check('u1', 'freeform', at(24 * H)), { allowed: false, rule: 'freeform_window_closed' });
  assert.deepEqual(check('u1', 'template', at(30 * H)), { allowed: true, rule: null });
});

ok('new inbound reopens the window (uses latest at, out-of-order safe)', () => {
  onInbound('u1', 'hello again', at(30 * H));
  onInbound('u1', 'older msg', at(29 * H));
  assert.deepEqual(check('u1', 'freeform', at(50 * H)), { allowed: true, rule: null });
});

const stopForms = ['STOP', 'stop', 'Stop.', '  STOP!! ', 'stop\n', 'Stop 🛑', 'UNSUBSCRIBE', 'cancel', 'End', 'QUIT', 'stopall', 'S​top'];
for (const form of stopForms) {
  ok(`opt-out keyword ${JSON.stringify(form)}`, () => {
    const u = 'stop-' + form.length + form.charCodeAt(0);
    onInbound(u, 'hi', at(0));
    onInbound(u, form, at(H));
    assert.equal(check(u, 'freeform', at(2 * H)).rule, 'opted_out');
    assert.equal(check(u, 'template', at(2 * H)).rule, 'opted_out');
  });
}

ok('ordinary sentences with stop words are not opt-outs', () => {
  for (const msg of ['please stop texting me about the bill', 'can you cancel my plan?', 'what time does the store close, end of day?', 'do not stop', 'stopping by tomorrow']) {
    onInbound('talker', msg, at(0));
  }
  assert.deepEqual(check('talker', 'template', at(H)), { allowed: true, rule: null });
});

ok('opt-out persists across later normal messages', () => {
  onInbound('u2', 'hi', at(0));
  onInbound('u2', 'STOP', at(H));
  onInbound('u2', 'actually I need help', at(2 * H));
  assert.equal(check('u2', 'template', at(3 * H)).rule, 'opted_out');
});

ok('START and UNSTOP re-enable; START itself opens the window', () => {
  onInbound('u3', 'hi', at(0));
  onInbound('u3', 'stop', at(H));
  onInbound('u3', 'Start', at(2 * H));
  assert.deepEqual(check('u3', 'freeform', at(3 * H)), { allowed: true, rule: null });
  onInbound('u3', 'stop', at(4 * H));
  onInbound('u3', 'unstop!', at(5 * H));
  assert.deepEqual(check('u3', 'template', at(6 * H)), { allowed: true, rule: null });
});

ok('"start" inside a sentence does not re-enable', () => {
  onInbound('u4', 'hi', at(0));
  onInbound('u4', 'stop', at(H));
  onInbound('u4', 'can we start over with my order', at(2 * H));
  assert.equal(check('u4', 'template', at(3 * H)).rule, 'opted_out');
});

ok('stop before any inbound still blocks, START before any inbound does not grant contact', () => {
  onInbound('u5', 'STOP', at(0));
  assert.equal(check('u5', 'template', at(H)).rule, 'opted_out');
  onInbound('u6', 'START', at(0));
  assert.equal(check('u6', 'template', at(H)).rule, 'no_prior_inbound' === '' ? '' : 'no_prior_inbound' );
});

ok('invalid inputs fail closed', () => {
  assert.equal(check('u1', 'sms', at(0)).rule, 'invalid_type');
  assert.equal(check('u1', 'freeform', new Date('x')).rule, 'invalid_time');
  assert.deepEqual(check('u1', 'freeform', at(0)).allowed, false);
});

ok('independent users do not share state', () => {
  onInbound('a', 'STOP', at(0));
  onInbound('b', 'hi', at(0));
  assert.equal(check('a', 'template', at(H)).rule, 'opted_out');
  assert.deepEqual(check('b', 'template', at(H)), { allowed: true, rule: null });
});

console.log(`\n${n} checks passed`);
