s=s.replace(/ok\(.stop before any inbound[\s\S]*?\n\}\);\n/, `ok("STOP before any inbound blocks; START as first message counts as inbound", () => {
  onInbound("u5", "STOP", at(0));
  assert.equal(check("u5", "template", at(H)).rule, "opted_out");
  onInbound("u6", "START", at(0));
  assert.deepEqual(check("u6", "template", at(H)), { allowed: true, rule: null });
});
`);
